    #[test]
    fn number_parse_primitive_text_borrows_exact_units_and_rejects_malformed_cells() {
        use varta_common::{abi, value};
        let units = (0..=u16::MAX)
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        let header = abi::OWNED_STRING_BASE;
        let cell = header + abi::STRING_HEADER_BYTES;
        let start = cell + value::UNION_BYTES;
        let mut bytes = vec![0; start + units.len()];
        for (index, word) in [
            32,
            value::HEAP_ALLOCATED_FLAG | value::HEAP_UNION_FLAG as u32,
            1,
            0,
            ValueKind::String as u32,
            1,
        ]
        .into_iter()
        .enumerate()
        {
            bytes[header + index * 4..header + index * 4 + 4].copy_from_slice(&word.to_le_bytes());
        }
        let packed = ((units.len() as u64) << 32) | start as u64;
        bytes[cell + value::UNION_META_BYTES..cell + value::UNION_BYTES]
            .copy_from_slice(&packed.to_le_bytes());
        bytes[start..].copy_from_slice(&units);
        let handle = (((value::UNION_BYTES as u64) << 32) | cell as u64) as i64;
        assert_eq!(&*text(&bytes, handle).unwrap(), units);
        for (offset, word) in [
            (header, 16),
            (header + 4, 0),
            (header + 8, 0),
            (cell, ValueKind::Record as u32),
            (cell + 4, 0),
            (cell + 12, 1),
        ] {
            let mut bad = bytes.clone();
            bad[offset..offset + 4].copy_from_slice(&word.to_le_bytes());
            assert!(text(&bad, handle).is_err(), "offset {offset}");
        }
        assert!(text(&bytes, handle ^ (1_i64 << 32)).is_err());
    }
